@NoRepositoryBean
interface InvoiceBaseRepo<T, ID> : CoroutineCrudRepository<T, ID>

interface InvoiceRepository : InvoiceBaseRepo<Invoice, Long> {
    suspend fun findByDueBefore(on: LocalDate): List<Invoice>

    @Query("select i from Invoice i where i.amount > :min")
    suspend fun findLarge(min: BigDecimal): List<Invoice>
}

object Invoices : LongIdTable("invoice") {
    val amount = decimal("amount", 10, 2)
    val due = date("due")
}

class ExposedInvoiceRepository(private val db: Database) : InvoiceRepository {
    override fun findOverdue(on: LocalDate): List<Invoice> = transaction(db) {
        Invoices.selectAll().where { Invoices.due less on }
            .map { it.toInvoice() }          // row -> domain object stays in this class
    }
}
